import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const b=JSON.parse('{"title":"EmakiItem","description":"","frontmatter":{},"headers":[],"relativePath":"modules/item/index.md","filePath":"modules/item/index.md","lastUpdated":null}'),r={name:"modules/item/index.md"};function i(c,t,s,l,n,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="emakiitem" tabindex="-1">EmakiItem <a class="header-anchor" href="#emakiitem" aria-label="Permalink to &quot;EmakiItem&quot;">​</a></h1><p>EmakiItem 是轻量自定义物品模块，提供稳定物品 ID、基础属性、套装、触发动作、自动更新与 PlaceholderAPI 支持。它适合作为装备成长线的起点：先生成一件有稳定 ID 的装备，再交给 Forge、Strengthen、Gem、Attribute 和 Skills 继续扩展。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.6.7</code></td></tr><tr><td>主命令</td><td><code>/emakiitem</code></td></tr><tr><td>别名</td><td><code>/ei</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiAttribute、EmakiSkills、MythicMobs、PlaceholderAPI</td></tr><tr><td>权限节点</td><td><code>emakiitem.use</code>、<code>emakiitem.give</code>、<code>emakiitem.inspect</code>、<code>emakiitem.update</code>、<code>emakiitem.reload</code>、<code>emakiitem.debug</code>、<code>emakiitem.admin</code></td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>列出与发放物品、检查手持物与组件、刷新物品与套装、重载与调试。</td></tr><tr><td><a href="./definitions.html">物品定义与套装</a></td><td><code>items/*.yml</code> 与 <code>sets/*.yml</code> 的字段、物品 ID 到 ItemStack 的生成规则。</td></tr><tr><td><a href="./triggers.html">触发器</a></td><td>交互、攻击、投射物、方块、丢弃等事件中执行动作。</td></tr><tr><td><a href="./update.html">物品更新策略</a></td><td>物品定义变更后把玩家手上的旧物品更新到新版本。</td></tr><tr><td><a href="./repair.html">物品修复系统</a></td><td>耐久归零后的禁用状态与材料/货币修复流程。</td></tr><tr><td><a href="./integration.html">跨模块集成</a></td><td>被 Attribute、Forge、Strengthen、Gem、Skills、Cooking 引用时的物品来源写法。</td></tr><tr><td><a href="./mythic.html">MythicMobs 集成</a></td><td>在 MythicMobs 的 <code>Drops</code> 中掉落 EmakiItem 物品。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>主手物品更新、重绘、修复、耐久与原版 Data Component 动作。</td></tr><tr><td><a href="./api.html">API</a></td><td>通过 <code>EmakiItemApi</code> 创建、识别与查询物品。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>物品流程的 Bukkit 事件与拦截点。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>稳定物品 ID</td><td>用配置 ID 标识物品，不依赖显示名。</td></tr><tr><td>物品组件</td><td>配置材质、名称、Lore、模型、附魔、flags、耐久等。</td></tr><tr><td>属性写入</td><td>可向 Attribute 提供属性 payload。</td></tr><tr><td>技能绑定</td><td>可让物品提供技能或技能解锁信息。</td></tr><tr><td>套装系统</td><td>根据装备件数触发属性、技能或 Lore。</td></tr><tr><td>触发器</td><td>在交互、攻击、投射物、方块、丢弃等事件中执行动作。</td></tr><tr><td>自动更新</td><td>玩家登录、切换手持、点击背包、拾取等场景刷新物品。</td></tr><tr><td>修复系统</td><td>耐久归零后进入禁用状态，可用材料或货币修复。</td></tr><tr><td>ID alias 与迁移</td><td>支持物品 ID 改名映射，并可批量迁移配置与玩家背包。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to &quot;默认配置目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiItem/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── id_aliases.yml</span></span>
<span class="line"><span>├── items/</span></span>
<span class="line"><span>├── sets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>items/</code> 定义物品，<code>sets/</code> 定义套装，<code>gui/</code> 存放修复界面模板，<code>id_aliases.yml</code> 保存物品 ID 改名映射。</p><h2 id="主配置" tabindex="-1">主配置 <a class="header-anchor" href="#主配置" aria-label="Permalink to &quot;主配置&quot;">​</a></h2><p><code>config.yml</code> 只包含全局设置，物品行为写在各自的定义文件里。</p><table tabindex="0"><thead><tr><th>配置键</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>当前模块版本</td><td>默认配置结构标识，不建议手动修改。</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>语言文件 ID，对应 <code>lang/&lt;language&gt;.yml</code>。</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>是否释放 <code>items/</code>、<code>sets/</code> 等默认示例数据。config.yml 与语言文件不受此项控制。</td></tr><tr><td><code>data_directories.max_depth</code></td><td>int</td><td><code>2</code></td><td><code>items/</code> 与 <code>sets/</code> 的子目录扫描层数上限（含数据目录本身）。<code>1</code> 只读根目录，<code>2</code> 允许一层子目录，<code>3</code> 允许两层。超限子目录会被跳过并输出控制台警告，最小值为 <code>1</code>。</td></tr><tr><td><code>set_bonus.enabled</code></td><td>boolean</td><td><code>true</code></td><td>是否启用套装加成系统。</td></tr><tr><td><code>set_bonus.refresh_triggers.join</code></td><td>boolean</td><td><code>true</code></td><td>玩家进服时刷新套装状态。</td></tr><tr><td><code>set_bonus.refresh_triggers.held_change</code></td><td>boolean</td><td><code>true</code></td><td>切换手持物品时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_click</code></td><td>boolean</td><td><code>true</code></td><td>点击背包时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_drag</code></td><td>boolean</td><td><code>true</code></td><td>拖拽物品时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.pickup</code></td><td>boolean</td><td><code>true</code></td><td>拾取物品时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.interact</code></td><td>boolean</td><td><code>true</code></td><td>交互时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.command</code></td><td>boolean</td><td><code>true</code></td><td>执行相关命令时允许刷新。</td></tr><tr><td><code>mythicmobs.enabled</code></td><td>boolean</td><td><code>true</code></td><td>MythicMobs 集成总开关。</td></tr><tr><td><code>mythicmobs.drops.enabled</code></td><td>boolean</td><td><code>true</code></td><td>是否注册 MythicMobs 自定义 Drop。</td></tr><tr><td><code>mythicmobs.drops.names</code></td><td>list</td><td><code>emakiitem</code>、<code>ei_item</code></td><td>可识别的 Drop 名称；为空时回退默认值。</td></tr></tbody></table><p><code>set_bonus.refresh_triggers</code> 控制套装状态刷新；物品自动更新由物品定义的 <code>update.triggers</code> 单独控制，二者互不覆盖。</p><h2 id="典型物品生命周期" tabindex="-1">典型物品生命周期 <a class="header-anchor" href="#典型物品生命周期" aria-label="Permalink to &quot;典型物品生命周期&quot;">​</a></h2><ol><li>在 <code>items/</code> 中定义物品 ID、材质、名称、Lore 和组件。</li><li>可选写入 Attribute 属性、Skills 技能或 set 信息。</li><li>管理员通过命令发放物品。</li><li>玩家使用装备。</li><li>Item 在触发时机自动更新物品状态。</li><li>Forge / Strengthen / Gem 可继续在该物品上写入自己的 layer。</li><li>CoreLib 统一重建最终展示。</li></ol><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to &quot;与其他模块的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>Item 写入基础属性或套装属性。</td></tr><tr><td>EmakiSkills</td><td>Item 写入装备技能 ID 与装备强制触发器；PDC 键由独立协议模块统一持有，不依赖 EmakiSkills 是否启用。</td></tr><tr><td>EmakiForge</td><td>Forge 可以改造 EmakiItem 生成的装备。</td></tr><tr><td>EmakiStrengthen</td><td>Strengthen 可以强化 EmakiItem 装备。</td></tr><tr><td>EmakiGem</td><td>Gem 可以给 EmakiItem 装备开孔和镶嵌。</td></tr><tr><td>MythicMobs</td><td>MythicMobs 怪物可以通过 <code>Drops</code> 掉落 EmakiItem 物品。</td></tr></tbody></table>`,19)])])}const p=d(r,[["render",i]]);export{b as __pageData,p as default};
